function CircuitViz({circuit}:{circuit:{qubits:number;gates:{name:string;qubits:number[];parameters:string[]}[]}}){
 const byQubit=Array.from({length:circuit.qubits},(_,qubit)=>({qubit,gates:circuit.gates.filter(g=>g.qubits.includes(qubit))}));
 return <div className="circuit-view" aria-label="Logical circuit visualization">
  <div className="circuit-view-head"><span>Qubit</span><span>Measured gates returned by backend</span></div>
  {byQubit.map(row=><div className="circuit-row" key={row.qubit}><strong>q[{row.qubit}]</strong><div className="circuit-wire">{row.gates.length?row.gates.map((gate,index)=><span className="circuit-gate" key={`${gate.name}-${index}`} title={gate.parameters.join(', ')}>{gate.name}{gate.parameters.length>0&&<small>{gate.parameters.join(', ')}</small>}</span>):<span className="circuit-idle">No gate on this wire</span>}</div></div>)}
 </div>;
}

function latestExperimentForDataset(experiments:Experiment[]|undefined,datasetId:string){
 return (experiments||[]).filter(experiment=>experiment.dataset_id===datasetId).sort((a,b)=>b.created_at.localeCompare(a.created_at))[0];
}

function contextModels(models:ModelRecord[]|undefined,experiments:Experiment[]|undefined,datasetId:string,scope:'active'|'all'){
 if(scope==='all'||!datasetId)return models||[];
 const experiment=latestExperimentForDataset(experiments,datasetId);
 return experiment?(models||[]).filter(model=>model.dataset_id===datasetId&&model.experiment_id===experiment.id):[];
}

function measuredDifference(quantum:number|null|undefined,classical:number|null|undefined){
 return quantum===null||quantum===undefined||classical===null||classical===undefined?null:quantum-classical;
}

export function Training(){
 const {draft,update,pipeline,quantum}=useDraft();
 const jobs=useQuery({queryKey:['jobs'],queryFn:qh.jobs,refetchInterval:3000});
 const dataset=useQuery({queryKey:['dataset',draft.dataset_id],queryFn:()=>qh.dataset(draft.dataset_id),enabled:Boolean(draft.dataset_id)});
 const library=useQuery({queryKey:['dataset-library'],queryFn:qh.datasetLibrary,staleTime:300000});
 const alignment=useQuery({queryKey:['alignment'],queryFn:qh.alignment,staleTime:300000});
 const readiness=library.data?.find(item=>item.slug===dataset.data?.provenance.library_slug)?.demo_readiness;
 const mutation=useMutation({mutationFn:()=>qh.createJob(draft),onSuccess:r=>{update({dataset_id:r.experiment.dataset_id});jobs.refetch()}});
 const qiskitSelected=draft.models.some(isQiskitQuantumModel);const hybridSelected=draft.models.some(isHybridModel);const quantumFamilySelected=draft.models.some(isQuantumFamilyModel);
 const dimensionsConflict=qiskitSelected&&hybridSelected&&draft.quantum.qubits!==draft.hybrid.qubits;
 const toggle=(kind:ModelKind)=>{const next=draft.models.includes(kind)?draft.models.filter(x=>x!==kind):[...draft.models,kind];const addsQiskit=isQiskitQuantumModel(kind)&&!draft.models.includes(kind);const addsHybrid=isHybridModel(kind)&&!draft.models.includes(kind);update({models:next});if(addsQiskit&&!next.some(isHybridModel))pipeline({pca_components:draft.quantum.qubits,angle_scaling:true});if(addsHybrid&&!next.some(isQiskitQuantumModel))pipeline({pca_components:draft.hybrid.qubits,angle_scaling:true})};
 const option=(kind:ModelKind,category:'Classical'|'Quantum'|'Hybrid quantum-classical',enabled=true)=>{const capability=alignment.data?.models.find(item=>item.model_id===kind);const runnable=enabled&&(capability?.executable??kind!=='hybrid_pennylane_torch');return <GlareHover key={kind}><button type="button" disabled={!runnable} aria-disabled={!runnable} onClick={()=>runnable&&toggle(kind)} className={'w-full rounded-xl border p-4 text-left transition disabled:cursor-not-allowed disabled:opacity-60 '+(draft.models.includes(kind)?'border-primary bg-primary/5':'hover:bg-muted')}><div className="flex items-center justify-between gap-2"><strong>{modelLabels[kind]}</strong><Badge tone={runnable?(draft.models.includes(kind)?(category==='Classical'?'blue':'purple'):'blue'):'amber'}>{runnable?(draft.models.includes(kind)?'Selected':category):(capability?.implementation_status||'Pending')}</Badge></div><small className="mt-1 block muted">{runnable?(category==='Classical'?'Classical baseline':category):capability?.implementation_status==='UNAVAILABLE'?'Dependencies unavailable — execution disabled':'Capability status loading'}</small></button></GlareHover>};
 return <div>
  <PageHeader eyebrow="01 / Train" title="Training" description="Configure one controlled experiment with shared partitions, preprocessing and evaluation conditions across supported classical and quantum models." actions={<Button disabled={!draft.dataset_id||!draft.models.length||mutation.isPending||dimensionsConflict} onClick={()=>mutation.mutate()}><Play size={14}/>{mutation.isPending?'Creating job…':'Create training experiment'}</Button>}/>
  <StageNav current="/training"/><ErrorBanner error={(mutation.error as Error)?.message}/>{readiness&&<Notice tone={readiness.status==='ready'?'blue':'amber'}>{readiness.status==='ready'?'A verified precomputed SIH demo is available for this dataset. You can still start a new live experiment.':'This dataset requires processing; no precomputed demo artifact is packaged. Live training remains available.'}</Notice>}
  <Card className="mt-5" title="Model families" description="Choose the estimators that receive the same configured representation.">
   <p className="metric-label mb-2">CLASSICAL BASELINES</p><div className="grid gap-3 md:grid-cols-3">{(['logistic_regression','svm','random_forest'] as ModelKind[]).map(x=>option(x,'Classical'))}</div>
   <div className="my-5 border-t"/><p className="metric-label mb-2">QISKIT QUANTUM MODELS</p>
   <div className="grid gap-3 md:grid-cols-3">{(['vqc','qsvc','qnn'] as ModelKind[]).map(x=>option(x,'Quantum'))}</div>
   <div className="my-5 border-t"/><p className="metric-label mb-2">PENNYLANE HYBRID · HYBRID QUANTUM-CLASSICAL</p>
   <div className="grid gap-3 md:grid-cols-3">{option('hybrid_pennylane_torch','Hybrid quantum-classical')}</div>
   {quantumFamilySelected&&<Notice>Quantum-family comparisons use one shared reduced representation, calibration disabled and no class-weighting. No quantum-advantage claim is made.</Notice>}{dimensionsConflict&&<Notice tone="amber">Qiskit and PennyLane qubits must match for the shared comparison representation.</Notice>}<p className="mt-3 text-xs muted">Shared comparison representation: {draft.pipeline.pca_components??'disabled'} dimensions</p>
  </Card>
  <div className="two-grid mt-5">
   <Card title="Shared evaluation contract" description="These settings are common to the selected model set."><div className="grid gap-4 md:grid-cols-2">
    <label className="field"><span>Random seed</span><Input type="number" value={draft.seed} onChange={e=>update({seed:Number(e.target.value)})}/></label>
    <label className="field"><span>Held-out test fraction</span><Input type="number" min=".1" max=".4" step=".05" value={draft.test_size} onChange={e=>update({test_size:Number(e.target.value)})}/></label>
    <label className="field"><span>CV folds</span><Input type="number" min="2" max="10" value={draft.cv_folds} onChange={e=>update({cv_folds:Number(e.target.value)})}/></label>
    <label className="field"><span>Maximum samples</span><Input type="number" min="30" value={draft.max_samples??''} onChange={e=>update({max_samples:e.target.value?Number(e.target.value):null})}/></label>
	    <label className="field"><span>Operating point</span><Select value={draft.threshold_strategy} onChange={e=>update({threshold_strategy:e.target.value as 'fixed'|'target_sensitivity'})}><option value="fixed">Fixed threshold</option><option value="target_sensitivity">Sensitivity-first</option></Select></label>
	    {draft.threshold_strategy==='fixed'?<label className="field"><span>Fixed research threshold</span><Input type="number" min=".01" max=".99" step=".01" value={draft.probability_threshold} onChange={e=>update({probability_threshold:Number(e.target.value)})}/></label>:<label className="field"><span>Target sensitivity</span><Input type="number" min=".01" max="1" step=".01" value={draft.target_sensitivity} onChange={e=>update({target_sensitivity:Number(e.target.value)})}/><small>Selected from out-of-fold validation; not a clinically validated screening cutoff.</small></label>}
    <label className="field"><span>Duplicate policy</span><Select value={draft.duplicate_policy} onChange={e=>update({duplicate_policy:e.target.value as any})}><option value="reject">Reject exact duplicates</option><option value="drop_exact">Drop exact duplicates</option></Select></label>
    <label className="field"><span>Calibration</span><Select disabled={quantumFamilySelected} value={draft.calibration} onChange={e=>update({calibration:e.target.value as any})}><option value="none">None</option><option value="sigmoid">Sigmoid / Platt</option><option value="isotonic">Isotonic</option></Select></label>
    <label className="field"><span>Calibration folds</span><Input type="number" min="2" max="5" disabled={draft.calibration==='none'||quantumFamilySelected} value={draft.calibration_folds} onChange={e=>update({calibration_folds:Number(e.target.value)})}/></label>
   </div></Card>
   <Card title="Classical parameters" description="Only values accepted by the backend training schema are exposed."><div className="grid gap-4 md:grid-cols-2">
    <label className="field"><span>Logistic C</span><Input type="number" min=".001" value={draft.parameters.logistic_c} onChange={e=>update({parameters:{...draft.parameters,logistic_c:Number(e.target.value)}})}/></label>
    <label className="field"><span>SVM / QSVC C</span><Input type="number" min=".001" value={draft.parameters.svm_c} onChange={e=>update({parameters:{...draft.parameters,svm_c:Number(e.target.value)}})}/></label>
    <label className="field"><span>SVM kernel</span><Select value={draft.parameters.svm_kernel} onChange={e=>update({parameters:{...draft.parameters,svm_kernel:e.target.value as any}})}><option value="rbf">RBF</option><option value="linear">Linear</option></Select></label>
    <label className="field"><span>Random forest trees</span><Input type="number" min="10" max="500" value={draft.parameters.forest_trees} onChange={e=>update({parameters:{...draft.parameters,forest_trees:Number(e.target.value)}})}/></label>
    <label className="field"><span>Forest maximum depth</span><Input type="number" min="1" max="100" value={draft.parameters.forest_max_depth??''} onChange={e=>update({parameters:{...draft.parameters,forest_max_depth:e.target.value?Number(e.target.value):null}})}/></label>
    <label className="field"><span>Class weighting</span><Select disabled={quantumFamilySelected} value={draft.parameters.class_weight||'none'} onChange={e=>update({parameters:{...draft.parameters,class_weight:e.target.value==='balanced'?'balanced':null}})}><option value="none">None</option><option value="balanced">Balanced</option></Select></label>
   </div></Card>
  </div>
  {qiskitSelected&&<BorderGlow className="mt-5"><Card title="Qiskit quantum configuration" description="QNN, VQC and QSVC use the existing Qiskit configuration contract.">
   <div className="grid gap-4 md:grid-cols-3">
    <label className="field"><span>Backend</span><Select value={draft.quantum.backend} onChange={e=>quantum({backend:e.target.value as any})}><option value="statevector">Statevector</option><option value="aer">Aer</option></Select></label>
    <label className="field"><span>Qubits</span><Input type="number" min="2" max="8" value={draft.quantum.qubits} onChange={e=>{const q=Number(e.target.value);quantum({qubits:q});if(qiskitSelected)pipeline({pca_components:q})}}/></label>
    <label className="field"><span>Feature-map reps</span><Input type="number" min="1" max="3" value={draft.quantum.feature_map_reps} onChange={e=>quantum({feature_map_reps:Number(e.target.value)})}/></label>
    <label className="field"><span>Ansatz reps</span><Input type="number" min="1" max="3" value={draft.quantum.ansatz_reps} onChange={e=>quantum({ansatz_reps:Number(e.target.value)})}/></label>
    <label className="field"><span>Entanglement</span><Select value={draft.quantum.entanglement} onChange={e=>quantum({entanglement:e.target.value as any})}><option value="linear">Linear</option><option value="full">Full</option></Select></label>
    <label className="field"><span>Optimizer</span><Select value={draft.quantum.optimizer} onChange={e=>quantum({optimizer:e.target.value as any})}><option value="COBYLA">COBYLA</option><option value="SPSA">SPSA</option></Select></label>
    <label className="field"><span>Maximum iterations</span><Input type="number" min="5" max="300" value={draft.quantum.maxiter} onChange={e=>quantum({maxiter:Number(e.target.value)})}/></label>
    <label className="field"><span>Shots</span><Input type="number" min="128" max="16384" value={draft.quantum.shots} onChange={e=>quantum({shots:Number(e.target.value)})}/></label>
    <label className="field"><span>Noise probability</span><Input type="number" min="0" max=".1" step=".01" disabled={draft.quantum.backend!=='aer'} value={draft.quantum.noise_probability} onChange={e=>quantum({noise_probability:Number(e.target.value)})}/></label>
   </div>
   <div className="mt-4 flex flex-wrap gap-4 text-xs"><label className="flex items-center gap-2"><input type="checkbox" checked={draft.pipeline.angle_scaling} onChange={e=>pipeline({angle_scaling:e.target.checked})}/>Shared angle scaling</label><label className="flex items-center gap-2"><input type="checkbox" checked={draft.pipeline.pca_components!==null} onChange={e=>pipeline({pca_components:e.target.checked?draft.quantum.qubits:null})}/>Enable PCA</label></div>
  </Card></BorderGlow>}
  {hybridSelected&&<BorderGlow className="mt-5"><Card title="PennyLane + PyTorch Hybrid" description="Classical preprocessing → PennyLane trainable quantum feature layer → expectation values → PyTorch classifier."><div className="grid gap-4 md:grid-cols-3"><label className="field"><span>Hybrid qubits</span><Input type="number" min="2" max="8" value={draft.hybrid.qubits} onChange={e=>{const qubits=Number(e.target.value);update({hybrid:{...draft.hybrid,qubits}});if(!qiskitSelected)pipeline({pca_components:qubits,angle_scaling:true})}}/></label><label className="field"><span>Quantum layers</span><Input type="number" min="1" max="6" value={draft.hybrid.quantum_layers} onChange={e=>update({hybrid:{...draft.hybrid,quantum_layers:Number(e.target.value)}})}/></label><label className="field"><span>Feature map</span><Input disabled value="AngleEmbedding"/></label><label className="field"><span>Hidden dimensions</span><Input value={draft.hybrid.classical_hidden_dimensions.join(",")} onChange={e=>update({hybrid:{...draft.hybrid,classical_hidden_dimensions:e.target.value.split(",").map(value=>Number(value.trim())).filter(Number.isFinite)}})}/></label><label className="field"><span>Activation</span><Select value={draft.hybrid.classical_activation} onChange={e=>update({hybrid:{...draft.hybrid,classical_activation:e.target.value as "relu"|"tanh"}})}><option value="relu">ReLU</option><option value="tanh">Tanh</option></Select></label><label className="field"><span>Optimizer</span><Select value={draft.hybrid.optimizer} onChange={e=>update({hybrid:{...draft.hybrid,optimizer:e.target.value as "adam"|"sgd"}})}><option value="adam">Adam</option><option value="sgd">SGD</option></Select></label><label className="field"><span>Learning rate</span><Input type="number" step="0.0001" value={draft.hybrid.learning_rate} onChange={e=>update({hybrid:{...draft.hybrid,learning_rate:Number(e.target.value)}})}/></label><label className="field"><span>Epochs</span><Input type="number" min="1" max="500" value={draft.hybrid.epochs} onChange={e=>update({hybrid:{...draft.hybrid,epochs:Number(e.target.value)}})}/></label><label className="field"><span>Batch size</span><Input type="number" min="1" max="256" value={draft.hybrid.batch_size} onChange={e=>update({hybrid:{...draft.hybrid,batch_size:Number(e.target.value)}})}/></label><label className="field"><span>Sample cap</span><Input type="number" min="30" max="2000" value={draft.hybrid.sample_cap} onChange={e=>update({hybrid:{...draft.hybrid,sample_cap:Number(e.target.value)}})}/></label><label className="field"><span>Backend</span><Input disabled value={draft.hybrid.backend}/></label></div><Notice tone="amber">CPU local simulation only. Hardware execution is unavailable; quantum advantage is not established.</Notice></Card></BorderGlow>}
  <Card className="mt-5" title="Execution state" description="Backend-reported jobs refresh automatically."><div className="space-y-3">{jobs.isLoading?<Loading/>:jobs.data?.length?jobs.data.slice(0,8).map(job=><div className="rounded-xl border p-3" key={job.id}><div className="flex items-center justify-between"><Link className="font-semibold text-primary" to={'/experiments/'+job.experiment_id}>Experiment {shortId(job.experiment_id)}</Link><StatusBadge value={job.status}/></div><p className="mt-1 text-xs muted">{job.state}</p><progress className="job-progress mt-2 w-full" max="100" value={job.progress}/><small className="block mt-1 muted">{job.progress}% backend-reported progress.</small>{['queued','running'].includes(job.status)&&<Button className="mt-2" variant="outline" onClick={()=>qh.cancelJob(job.id).then(()=>jobs.refetch())}>Request cancellation</Button>}{job.errors.length>0&&<JsonDisclosure label="Recorded model failures" value={job.errors}/>}</div>):<EmptyState title="No training jobs">Create an experiment to populate the execution registry.</EmptyState>}</div></Card>
 </div>;
}

export function Comparison(){
 const {draft}=useDraft();
 const experiments=useQuery({queryKey:['experiments'],queryFn:qh.experiments});
 const [scope,setScope]=useState<'active'|'all'>(draft.dataset_id?'active':'all');
 const [id,setId]=useState('');
 const visibleExperiments=scope==='active'&&draft.dataset_id?(experiments.data||[]).filter(item=>item.dataset_id===draft.dataset_id):experiments.data||[];
 const selected=useQuery({queryKey:['comparison',id],queryFn:()=>qh.comparison(id),enabled:Boolean(id),refetchInterval:5000});
 const [modelId,setModelId]=useState('');
 const [pairKey,setPairKey]=useState('');
 useEffect(()=>{if(!visibleExperiments.some(item=>item.id===id)){setId(visibleExperiments[0]?.id||'');setModelId('');setPairKey('')}},[id,scope,draft.dataset_id,experiments.data]);
 const data=selected.data;
 const model=data?.models.find(item=>item.id===modelId)||data?.models.find(item=>item.status==='ready')||data?.models[0];
 const pair=data?.pairs.find(item=>`${item.quantum_model}:${item.classical_model}`===pairKey)||data?.pairs[0];
 const evidenceMetrics=['accuracy','sensitivity','specificity','f1','roc_auc'] as const;
 const operating=model?.metrics.operating_point;
 return <div>
  <PageHeader eyebrow="02 / Compare" title="Model comparison" description="Controlled held-out evidence with measured model deltas, runtime, logical quantum resources and neutral interpretation." actions={<Link className="btn btn-outline" to="/explainability"><ArrowRight size={14}/>Explainability</Link>}/>
  <StageNav current="/comparison"/><ErrorBanner error={(experiments.error as Error)?.message||(selected.error as Error)?.message}/>
  <Card className="mt-5" title="Experiment context"><div className="grid gap-4 md:grid-cols-2"><label className="field"><span>Record scope</span><Select aria-label="Comparison record scope" value={scope} onChange={e=>setScope(e.target.value as 'active'|'all')}><option value="active" disabled={!draft.dataset_id}>Active dataset + latest workflow</option><option value="all">All registered models</option></Select></label><label className="field"><span>Experiment</span><Select value={id} onChange={e=>{setId(e.target.value);setModelId('');setPairKey('')}}><option value="">Select experiment</option>{visibleExperiments.map(item=><option value={item.id} key={item.id}>{shortId(item.id)} · {item.status}</option>)}</Select></label></div>{scope==='active'&&<Notice tone="blue">Only experiments for the active dataset are shown. Historical experiments remain available through “All registered models”.</Notice>}</Card>
  {selected.isLoading&&id&&<div className="mt-4"><Loading/></div>}
  {data&&<>
   <Card className="mt-5" title="Held-out performance" description={data.conclusion}><div className="table-wrap"><table className="data-table"><thead><tr><th>Model</th><th>Status</th>{metricNames.map(name=><th key={name}>{name}</th>)}</tr></thead><tbody>{data.models.map(item=><tr key={item.id} className={model?.id===item.id?'bg-primary/5':''}><td><button className="font-semibold text-primary" onClick={()=>setModelId(item.id)}>{modelLabels[item.model_type]}</button></td><td><StatusBadge value={item.status}/></td>{metricNames.map(name=><td key={name}>{metric(item.metrics.test?.[name],name!=='roc_auc')}</td>)}</tr>)}</tbody></table></div></Card>
   {operating&&<div className="two-grid mt-5"><Card title="Research operating point" description={operating.interpretation}>{operating.threshold_feasible?<div className="grid grid-cols-3 gap-3"><MetricCard label="THRESHOLD" value={operating.selected_threshold===null?'—':operating.selected_threshold.toFixed(4)} detail={operating.threshold_source}/><MetricCard label="VALIDATION SENSITIVITY" value={metric(operating.validation_metrics?.sensitivity)} detail="Out-of-fold"/><MetricCard label="VALIDATION SPECIFICITY" value={metric(operating.validation_metrics?.specificity)} detail="Out-of-fold"/></div>:<Notice tone="amber">{operating.infeasible_reason||'Target sensitivity is not achievable on the validation folds under the current model configuration.'}</Notice>}</Card><Card title="Validation threshold trade-off"><ThresholdTradeoffChart operatingPoint={operating}/></Card></div>}
   <div className="two-grid mt-5">{model?.metrics.test&&<Card title={modelLabels[model.model_type]+' · held-out metrics'}><MetricBars metrics={model.metrics.test}/><JsonDisclosure label="Confusion matrix and metric record" value={model.metrics.test}/></Card>}<Card title="ROC comparison"><RocChart models={data.models}/></Card></div>
   <Card className="mt-5" title="Validation, holdout, and runtime"><div className="table-wrap"><table className="data-table"><thead><tr><th>Metric</th><th>CV mean</th><th>CV SD</th><th>Test</th></tr></thead><tbody>{metricNames.map(name=><tr key={name}><td>{name}</td><td>{metric(model?.metrics.validation?.summary?.[name]?.mean,name!=='roc_auc')}</td><td>{metric(model?.metrics.validation?.summary?.[name]?.std,name!=='roc_auc')}</td><td>{metric(model?.metrics.test?.[name],name!=='roc_auc')}</td></tr>)}</tbody></table></div></Card>
   <Card className="mt-5" title={pair?.quantum_type==='hybrid_pennylane_torch'?'Classical vs hybrid evidence':'Classical vs quantum evidence'} description="Persisted backend evidence reports observed differences without ranking.">
    {data.pairs.length?<><label className="field"><span>Evidence pair</span><Select aria-label="Evidence pair" value={pair?`${pair.quantum_model}:${pair.classical_model}`:''} onChange={e=>setPairKey(e.target.value)}>{data.pairs.map(item=><option key={`${item.quantum_model}:${item.classical_model}`} value={`${item.quantum_model}:${item.classical_model}`}>{modelLabels[item.quantum_type]} vs {modelLabels[item.classical_type]}</option>)}</Select></label>{pair&&<EvidencePanel pair={pair}/>}</>:<EmptyState title="No classical / quantum pair">Complete at least one classical and one quantum model in the same experiment.</EmptyState>}
   </Card>
   <JsonDisclosure label="Comparison conditions and complete evidence" value={{split:data.split,fingerprint:data.comparison_fingerprint,limitations:data.limitations,pairs:data.pairs}}/>
  </>}
 </div>;
}

function EvidencePanel({pair}:{pair:EvidencePair}){
 const metrics=['sensitivity','specificity','precision','recall','f1','roc_auc','accuracy'] as const;
 const costs:[string,keyof EvidencePair['computational_cost']['classical']][]=[['Final training','final_training_seconds'],['CV total','cv_total_seconds'],['Mean CV fold','cv_mean_fold_seconds'],['Test inference','test_inference_seconds'],['Inference / sample','test_inference_seconds_per_sample']];
 const resources=pair.quantum_resources;
 const fairness=pair.fairness;
 const controlled=Boolean(fairness.controlled_comparison);
 const status=fairness.status||(controlled?'CONTROLLED COMPARISON':'NOT CONTROLLED');
 const representation=(pair.common_representation||fairness.common_representation||{}) as Record<string,unknown>;
 const classicalName=pair.model_identities?.classical.display_name||modelLabels[pair.classical_type];
 const comparisonIdentity=pair.model_identities?.quantum_or_hybrid||pair.model_identities?.hybrid;
 const quantumName=comparisonIdentity?.display_name||modelLabels[pair.quantum_type];
 const isHybrid=pair.quantum_type==='hybrid_pennylane_torch';
 const comparisonRole=isHybrid?'Hybrid':'Quantum';
 return <div className="mt-4 space-y-5">
  {pair.benchmark_type==='fair_controlled_diabetes_benchmark'&&<div>
   <div className="metric-label mb-2">{controlled?'CONTROLLED DIABETES BENCHMARK':'DIABETES BENCHMARK FAIRNESS CHECK'}</div>
   <Notice tone={controlled?'green':'amber'}><strong>{status}</strong>{fairness.mismatch_reasons?.length?` — ${fairness.mismatch_reasons.join(', ')}`:' — fairness conditions were verified from persisted backend metadata.'}</Notice>
   <div className="mt-3 grid gap-3 md:grid-cols-3">
    <MetricCard label="DATASET" value={fairness.target||'Early Stage Diabetes Risk Prediction'} detail={`${fairness.dataset_id} · SHA-256 ${fairness.dataset_hash||'not recorded'}`}/>
    <MetricCard label="SHARED SAMPLES" value={fairness.realized_evaluated_sample_count??fairness.common_sample_count??'—'} detail={`Configured ${fairness.configured_sample_budget??'—'} · same realized budget = ${fairness.same_sample_budget?'true':'false'}`}/>
    <MetricCard label="SHARED SPLIT" value={fairness.split_match?'verified':'not verified'} detail={fairness.split_hash||'Split hash not recorded'}/>
    <MetricCard label="PCA / QUBITS" value={`${String(representation.pca_components??'—')} / ${String(representation.hybrid_qubits??resources.qubits??'—')}`} detail={`${String(representation.selected_feature_count??'—')} selected features`}/>
    <MetricCard label="CV FOLDS" value={fairness.cv_fold_count??'—'} detail={`Seed ${fairness.seed??'—'} · test size ${fairness.test_size??'—'}`}/>
    <MetricCard label="THRESHOLD STRATEGY" value={fairness.threshold_strategy} detail={`Target sensitivity ${fairness.target_sensitivity??'—'}`}/>
   </div>
  </div>}
  <div><div className="metric-label mb-2">SHARED HELD-OUT BENCHMARK</div><div className="table-wrap"><table className="data-table"><thead><tr><th>Metric</th><th>{classicalName}</th><th>{quantumName}</th><th>{`Observed difference (${comparisonRole} − Classical)`}</th></tr></thead><tbody>{metrics.map(name=><tr key={name}><td>{name}</td><td>{metric(pair.performance[name].classical,name!=='roc_auc')}</td><td>{metric(pair.performance[name].quantum,name!=='roc_auc')}</td><td>{metric(pair.performance[name].delta_quantum_minus_classical,name!=='roc_auc')}</td></tr>)}</tbody></table></div></div>
  <div className="two-grid">
   <Card title="OOF validation threshold" description="Selected only from training cross-validation predictions, then frozen."><div className="space-y-2 text-xs"><div className="flex justify-between"><span>{classicalName} threshold</span><strong>{pair.operating_points.classical.selected_threshold??'undefined'}</strong></div><div className="flex justify-between"><span>{quantumName} threshold</span><strong>{pair.operating_points.quantum.selected_threshold??'undefined'}</strong></div><div className="flex justify-between"><span>{classicalName} OOF samples</span><strong>{pair.operating_points.classical.number_of_oof_samples??'—'}</strong></div><div className="flex justify-between"><span>{quantumName} OOF samples</span><strong>{pair.operating_points.quantum.number_of_oof_samples??'—'}</strong></div></div></Card>
   <Card title="Untouched holdout evaluation" description="Both models were evaluated on the identical persisted test indices."><div className="space-y-2 text-xs"><div className="flex justify-between"><span>{classicalName} sensitivity / specificity</span><strong>{metric(pair.operating_points.classical.holdout_metrics?.sensitivity)} / {metric(pair.operating_points.classical.holdout_metrics?.specificity)}</strong></div><div className="flex justify-between"><span>{quantumName} sensitivity / specificity</span><strong>{metric(pair.operating_points.quantum.holdout_metrics?.sensitivity)} / {metric(pair.operating_points.quantum.holdout_metrics?.specificity)}</strong></div></div></Card>
  </div>
  <div><div className="metric-label mb-2">COMPUTATIONAL MEASUREMENTS</div><div className="table-wrap"><table className="data-table"><thead><tr><th>Measure</th><th>{classicalName}</th><th>{quantumName}</th><th>Observed difference</th></tr></thead><tbody>{costs.map(([label,key])=><tr key={key}><td>{label}</td><td>{seconds(pair.computational_cost.classical[key])}</td><td>{seconds(pair.computational_cost.quantum[key])}</td><td>{seconds(pair.computational_cost.deltas_quantum_minus_classical[key])}</td></tr>)}</tbody></table></div><p className="mt-2 text-xs muted">{pair.computational_cost.semantics}</p></div>
  <div><div className="metric-label mb-2">{isHybrid?'HYBRID EXECUTION CONTEXT':'QUANTUM EXECUTION CONTEXT'}</div><div className="grid gap-3 md:grid-cols-4"><MetricCard label="BACKEND" value={resources.backend||'Not recorded'} detail={resources.execution_kind||'Execution not recorded'}/><MetricCard label={isHybrid?'QUBITS / LAYERS':'QUBITS / DEPTH'} value={isHybrid?`${resources.qubits??'—'} / ${resources.quantum_layers??'—'}`:`${resources.qubits??'—'} / ${resources.logical_depth??'—'}`} detail={resources.shots===null||resources.shots===undefined?(isHybrid?'Exact expectations · no shots configured':'Shots not recorded'):`${resources.shots} shots`}/><MetricCard label="PARAMETERS" value={resources.trainable_parameter_count??'—'} detail={`${resources.total_parameter_count??'—'} total · ${resources.optimizer||'optimizer not recorded'}`}/><MetricCard label="REAL HARDWARE" value={resources.real_hardware?'true':'false'} detail={resources.timing_label||'Simulator execution'}/></div><p className="mt-2 text-xs muted">{resources.resource_semantics}</p></div>
  <div><div className="metric-label mb-2">PAIRED ROBUSTNESS</div><Notice tone="blue">{pair.robustness.note}</Notice></div>
  <Notice tone="blue"><strong>Neutral interpretation:</strong> {pair.conclusion}</Notice>
  <Notice tone="amber"><strong>Scientific limitations:</strong> {pair.limitations.join(' ')}</Notice>
 </div>;
}

export function Robustness(){
 const {draft}=useDraft();
 const experiments=useQuery({queryKey:['experiments'],queryFn:qh.experiments});
 const models=useQuery({queryKey:['models'],queryFn:qh.models});
 const [scope,setScope]=useState<'active'|'all'>(draft.dataset_id?'active':'all');
 const [experimentId,setExperimentId]=useState('');
 const [classicalId,setClassicalId]=useState('');
 const [quantumId,setQuantumId]=useState('');
 const [kind,setKind]=useState<PerturbationType>('missingness');
 const [level,setLevel]=useState(.05);
 const [seed,setSeed]=useState(42);
 const [maxSamples,setMaxSamples]=useState(32);
 const visibleExperiments=scope==='active'&&draft.dataset_id?(experiments.data||[]).filter(item=>item.dataset_id===draft.dataset_id):experiments.data||[];
 const experimentModels=(models.data||[]).filter(model=>model.experiment_id===experimentId&&model.status==='ready');
 const classical=experimentModels.filter(model=>!isQuantumFamilyModel(model.model_type));
 const quantumModels=experimentModels.filter(model=>isQuantumFamilyModel(model.model_type));
 const levels=kind==='outliers'?[3]:[.05,.1];
 useEffect(()=>{if(!visibleExperiments.some(item=>item.id===experimentId)){setExperimentId(visibleExperiments[0]?.id||'');setClassicalId('');setQuantumId('')}},[scope,draft.dataset_id,experiments.data,experimentId]);
 useEffect(()=>{if(!levels.includes(level))setLevel(levels[0])},[kind]);
 const run=useMutation({mutationFn:()=>qh.robustness(experimentId,{model_ids:[classicalId,quantumId].filter(Boolean),scenarios:[{perturbation_type:kind,level}],random_seed:seed,max_samples:maxSamples})});
 const records=run.data?.results||[];
 const shownMetrics=['accuracy','sensitivity','specificity','f1','roc_auc'] as const;
 return <div>
  <PageHeader eyebrow="03 / Robustness" title="Robustness Lab" description="Measure frozen classical and quantum model behavior under identical, deterministic perturbations of the same bounded held-out samples." actions={<Link className="btn btn-outline" to="/comparison"><ArrowRight size={14}/>Comparison</Link>}/>
  <StageNav current="/robustness"/><ErrorBanner error={(experiments.error as Error)?.message||(models.error as Error)?.message||(run.error as Error)?.message}/>
  <Notice tone="amber">Research evaluation only. The locked research operating threshold remains unchanged; models are not refit and no clinical robustness or quantum advantage is claimed.</Notice>
  <Card className="mt-5" title="Controlled benchmark condition" description="Select one bounded perturbation. Both selected models receive the same perturbed sample matrix and seed.">
   <div className="grid gap-4 md:grid-cols-3">
    <label className="field"><span>Record scope</span><Select aria-label="Robustness record scope" value={scope} onChange={event=>setScope(event.target.value as 'active'|'all')}><option value="active" disabled={!draft.dataset_id}>Active dataset + latest workflow</option><option value="all">All registered models</option></Select></label>
    <label className="field"><span>Experiment</span><Select aria-label="Robustness experiment" value={experimentId} onChange={event=>{setExperimentId(event.target.value);setClassicalId('');setQuantumId('')}}><option value="">Select experiment</option>{visibleExperiments.map(item=><option value={item.id} key={item.id}>{shortId(item.id)} · {item.status}</option>)}</Select></label>
    <label className="field"><span>Scenario</span><Select aria-label="Perturbation scenario" value={kind} onChange={event=>setKind(event.target.value as PerturbationType)}><option value="missingness">Missingness</option><option value="gaussian_noise">Gaussian noise</option><option value="outliers">Numerical outliers</option><option value="categorical">Categorical perturbation</option></Select></label>
    <label className="field"><span>Level</span><Select aria-label="Perturbation level" value={level} onChange={event=>setLevel(Number(event.target.value))}>{levels.map(value=><option value={value} key={value}>{kind==='outliers'?`±${value} training SD`:`${Math.round(value*100)}%`}</option>)}</Select></label>
    <label className="field"><span>Classical model</span><Select aria-label="Classical robustness model" value={classicalId} onChange={event=>setClassicalId(event.target.value)}><option value="">None</option>{classical.map(model=><option value={model.id} key={model.id}>{modelLabels[model.model_type]} · {shortId(model.id)}</option>)}</Select></label>
    <label className="field"><span>Quantum model</span><Select aria-label="Quantum robustness model" value={quantumId} onChange={event=>setQuantumId(event.target.value)}><option value="">None</option>{quantumModels.map(model=><option value={model.id} key={model.id}>{modelLabels[model.model_type]} · {shortId(model.id)}</option>)}</Select></label>
    <label className="field"><span>Random seed</span><Input aria-label="Robustness random seed" type="number" value={seed} onChange={event=>setSeed(Number(event.target.value))}/></label>
    <label className="field"><span>Maximum held-out samples</span><Input aria-label="Robustness maximum samples" type="number" min="8" max="64" value={maxSamples} onChange={event=>setMaxSamples(Number(event.target.value))}/></label>
   </div>
   <Button className="mt-4" disabled={!experimentId||(!classicalId&&!quantumId)||run.isPending} onClick={()=>run.mutate()}><Play size={14}/>{run.isPending?'Evaluating controlled perturbation…':'Run robustness condition'}</Button>
  </Card>
  {run.isPending&&<div className="mt-5"><Loading/></div>}
  {run.data&&<div className="mt-5 space-y-5">
   <Card title="Observed degradation under controlled perturbation" description={`Benchmark condition: ${kind.replaceAll('_',' ')} at ${level}. Degradation Δ means perturbed − baseline.`}><RobustnessDeltaChart records={records}/></Card>
   <div className="grid gap-5 lg:grid-cols-2">{records.map(record=><RobustnessResult key={record.id||record.model_id} record={record} metrics={shownMetrics}/>)}</div>
   {records.length===2&&records.every(record=>record.status==='evaluated')&&<Card title="Paired observed differences" description="The values below compare each model's degradation delta (quantum − classical). They are descriptive measurements, not a winner or advantage claim."><div className="table-wrap"><table className="data-table"><thead><tr><th>Metric</th><th>Quantum Δ − Classical Δ</th></tr></thead><tbody>{shownMetrics.map(name=><tr key={name}><td>{name}</td><td>{metric(measuredDifference(records.find(record=>isQuantumFamilyModel(record.model_type))?.degradation_delta[name],records.find(record=>!isQuantumFamilyModel(record.model_type))?.degradation_delta[name]),name!=='roc_auc')}</td></tr>)}</tbody></table></div></Card>}
   <JsonDisclosure label="Reproducibility metadata and limitations" value={run.data}/>
  </div>}
 </div>;
}

function RobustnessResult({record,metrics}:{record:RobustnessEvidence;metrics:readonly ('accuracy'|'sensitivity'|'specificity'|'f1'|'roc_auc')[]}){
 return <Card title={modelLabels[record.model_type]} description={`${record.perturbation_type.replaceAll('_',' ')} · seed ${record.random_seed} · ${record.sample_count} held-out samples`}>
  {record.status!=='evaluated'?<Notice tone="amber"><strong>{record.status.replaceAll('_',' ')}:</strong> {record.reason||'This condition could not be evaluated.'}</Notice>:<div className="table-wrap"><table className="data-table"><thead><tr><th>Metric</th><th>Baseline</th><th>Perturbed</th><th>Δ</th></tr></thead><tbody>{metrics.map(name=><tr key={name}><td>{name}</td><td>{metric(record.baseline_metrics[name],name!=='roc_auc')}</td><td>{metric(record.perturbed_metrics?.[name],name!=='roc_auc')}</td><td>{metric(record.degradation_delta[name],name!=='roc_auc')}</td></tr>)}</tbody></table></div>}
  <p className="mt-3 text-xs muted">Threshold {record.threshold_used.toFixed(4)} · {record.threshold_source.replaceAll('_',' ')} · frozen model, no threshold reselection.</p>
 </Card>;
}

export function Quantum(){
 const {draft,update,pipeline,quantum}=useDraft(); const cap=useQuery({queryKey:['quantum-capabilities'],queryFn:qh.capabilities}); const [kind,setKind]=useState<'vqc'|'qsvc'|'qnn'>('vqc');const [circuit,setCircuit]=useState<any>();const [modelId,setModelId]=useState('');const [mode,setMode]=useState<'explain'|'technical'>('explain');const models=useQuery({queryKey:['models'],queryFn:qh.models});const preview=useMutation({mutationFn:()=>qh.circuit({quantum:draft.quantum,model_type:kind,seed:draft.seed}),onSuccess:setCircuit});const fitted=useMutation({mutationFn:()=>qh.fittedCircuit(modelId),onSuccess:setCircuit});const advisor=useMutation({mutationFn:()=>qh.resourceAdvisor({model_type:kind,quantum:draft.quantum,feature_dimension:draft.pipeline.pca_components??draft.quantum.qubits,sample_count:draft.max_samples??160,dataset_id:draft.dataset_id||null,experiment_id:null})});
 const advice=advisor.data;const history=advice?.historical_evidence;const applyRecommendation=()=>{const recommendation=advice?.recommendation.configuration;if(!recommendation)return;quantum(recommendation.quantum);pipeline({pca_components:recommendation.feature_dimension,angle_scaling:true});update({max_samples:recommendation.sample_count})};
 return <div><PageHeader eyebrow="Quantum Lab" title="Quantum circuit" description="Inspect logical circuits and plan bounded simulator experiments without turning resource dimensions into unsupported runtime or hardware claims." actions={<Link className="btn btn-outline" to="/training"><ArrowRight size={14}/>Configure in Model Lab</Link>}/><StageNav current="/quantum"/><ErrorBanner error={(cap.error as Error)?.message||(models.error as Error)?.message||(preview.error as Error)?.message||(fitted.error as Error)?.message||(advisor.error as Error)?.message}/><Reveal className="mb-5"><SpotlightPanel className="rb-quantum-stage p-4"><div className="flex flex-wrap items-center gap-5"><QuantumVisual/><div className="max-w-md"><div className="eyebrow">STRUCTURAL QUANTUM VIEW</div><h2 className="section-title mt-2">Logical circuits, measured honestly.</h2><p className="section-copy mt-2">The ambient visual communicates circuit structure only; every value below comes from the existing backend contract.</p></div></div></SpotlightPanel></Reveal><div className="mt-5 two-grid"><Card title="Quantum capability"><div className="grid gap-3"><div className="flex justify-between text-sm"><span className="muted">Dependencies</span><StatusBadge value={cap.data?.available?'ready':'unavailable'}/></div><p className="text-xs muted">{cap.data?.execution||'Loading quantum runtime capability…'}</p><label className="field"><span>Model</span><Select aria-label="Quantum advisor model" value={kind} onChange={e=>setKind(e.target.value as any)}><option value="vqc">VQC</option><option value="qsvc">QSVC</option><option value="qnn">QNN</option></Select></label><Button disabled={cap.data?.available===false||preview.isPending} onClick={()=>preview.mutate()}><Play size={14}/>{preview.isPending?'Generating…':'Generate circuit representation'}</Button></div></Card><Card title="Registered quantum model"><ModelSelect models={models.data||[]} value={modelId} onChange={setModelId} quantumOnly/><Button className="mt-3" disabled={!modelId||fitted.isPending} onClick={()=>fitted.mutate()} variant="outline">Retrieve fitted circuit</Button></Card></div>
 <Card className="mt-5" title="Quantum Resource Advisor" description="Cheap deterministic planning against the bounded prototype resource policy. The advisor never starts training or silently edits the draft.">
  <div className="grid gap-3 md:grid-cols-4"><MetricCard label="BACKEND" value={draft.quantum.backend} detail={draft.quantum.noise_probability?`Noise ${draft.quantum.noise_probability}`:'No configured noise'}/><MetricCard label="QUBITS / PCA" value={`${draft.quantum.qubits} / ${draft.pipeline.pca_components??'off'}`} detail="Logical width / feature dimension"/><MetricCard label="CIRCUIT REPS" value={`${draft.quantum.feature_map_reps} + ${draft.quantum.ansatz_reps}`} detail="Feature map + ansatz"/><MetricCard label="ITERATIONS / SHOTS" value={`${draft.quantum.maxiter} / ${draft.quantum.shots}`} detail={`${draft.quantum.optimizer} · ${draft.max_samples??160} samples`}/></div>
  <Button className="mt-4" disabled={advisor.isPending} onClick={()=>advisor.mutate()}><SlidersHorizontal size={14}/>{advisor.isPending?'Analyzing configuration…':'Analyze resource profile'}</Button>
 </Card>
 {advice&&<div className="mt-5 space-y-5">
  <Card title="Resource profile" description={advice.budget_policy.semantics}><div className="grid gap-3 md:grid-cols-3"><MetricCard label="CIRCUIT COMPLEXITY" value={advice.resource_profile.circuit_complexity.toUpperCase()} detail={`${advice.resource_profile.logical_qubits} qubits · ${advice.resource_profile.entanglement} entanglement`}/><MetricCard label="OPTIMIZATION" value={advice.resource_profile.optimization_workload.toUpperCase()} detail={`${advice.resource_profile.optimizer_iteration_budget} requested iterations`}/><MetricCard label="MEASUREMENT" value={advice.resource_profile.measurement_workload.replaceAll('_',' ').toUpperCase()} detail={advice.resource_profile.shots_per_circuit_evaluation===null?'Exact statevector; configured shots are unused':`${advice.resource_profile.shots_per_circuit_evaluation} shots`}/><MetricCard label="SAMPLE WORKLOAD" value={advice.resource_profile.sample_workload.toUpperCase()} detail={`${advice.resource_profile.sample_count} / ${advice.resource_profile.bounded_quantum_sample_cap} bounded samples`}/><MetricCard label="BUDGET STATUS" value={advice.budget_status.status.replaceAll('_',' ').toUpperCase()} detail={advice.budget_policy.version}/><MetricCard label="EXECUTION" value="SIMULATOR" detail={advice.resource_profile.execution_kind}/></div><Notice tone={advice.budget_status.status==='exceeds_budget'?'amber':'blue'}>{advice.budget_status.reasons.join(' ')}</Notice></Card>
  <Card title="Configuration recommendation" description={advice.recommendation.rationale}>{advice.recommendation.available?<><div className="table-wrap"><table className="data-table"><thead><tr><th>Parameter</th><th>Requested</th><th>Recommended</th><th>Reason</th></tr></thead><tbody>{advice.recommendation.changes.map(change=><tr key={change.field}><td>{change.field}</td><td>{change.from}</td><td>{change.to}</td><td>{change.reason}</td></tr>)}</tbody></table></div><Button className="mt-4" onClick={applyRecommendation}>Apply recommended configuration</Button><p className="mt-2 text-xs muted">Explicit action only. Applying updates the existing draft, matching PCA to qubits; it does not start training.</p></>:<Notice tone="blue">Configuration is within the bounded prototype resource policy. No draft changes are recommended.</Notice>}</Card>
  <Card title="Observed historical runs" description={history?.matching_policy}>{history&&history.matched_runs>0?<div className="grid gap-3 md:grid-cols-3"><MetricCard label="MATCHED RUNS" value={history.matched_runs} detail="Recorded completed models"/><MetricCard label="MEDIAN TRAINING" value={seconds(history.median_training_seconds)} detail="Observed, not estimated"/><MetricCard label="OBSERVED RANGE" value={`${seconds(history.min_training_seconds)} – ${seconds(history.max_training_seconds)}`} detail="Recorded final-fit timing"/></div>:<Notice>Insufficient historical evidence for a measured runtime comparison.</Notice>}<p className="mt-3 text-xs muted">Observed historical runtime is not a guaranteed runtime estimate for this request.</p></Card>
  <Notice tone="amber">Hardware execution is not available in the current verified configuration. Logical resources and simulator workload do not predict real-QPU wall-clock performance.</Notice>
 </div>}
 {circuit?<Card className="mt-5" title={String(circuit.model_type).toUpperCase() + ' · ' + circuit.execution_kind} description={circuit.limitation}><div className="mode-tabs" role="tablist" aria-label="Quantum view mode"><button className={mode==='explain'?'is-active':''} onClick={()=>setMode('explain')} role="tab" aria-selected={mode==='explain'}>Explain mode</button><button className={mode==='technical'?'is-active':''} onClick={()=>setMode('technical')} role="tab" aria-selected={mode==='technical'}>Technical mode</button></div>{mode==='explain'?<div className="quantum-explain-grid mt-4">{['Classical features','Encoding / feature map','Parameterized ansatz','Measurement','Classical optimization'].map((step,index)=><div className="quantum-explain-step" key={step}><span>{String(index+1).padStart(2,'0')}</span><strong>{step}</strong><small>{index===0?'The configured input representation enters the circuit.':index===1?'Features are encoded into logical qubit rotations.':index===2?'Trainable circuit parameters are evaluated by the selected runtime.':index===3?'The backend measures the circuit output for the estimator.':'A classical optimizer updates parameters during training.'}</small></div>)}</div>:<div className="grid gap-3 md:grid-cols-3 mt-4"><MetricCard label="BACKEND" value={circuit.backend} detail="Reported execution target"/><MetricCard label="EXECUTION" value={circuit.execution_kind} detail="Reported mode"/><MetricCard label="GATE TYPES" value={Object.keys(circuit.gate_counts).length} detail="Returned gate categories"/></div>}<div className="grid grid-cols-3 gap-3 mt-5"><MetricCard label="QUBITS" value={circuit.qubits} detail="Logical width" icon={<Atom size={15}/>}/><MetricCard label="DEPTH" value={circuit.logical_depth} detail="Logical depth" icon={<BarChart3 size={15}/>}/><MetricCard label="PARAMETERS" value={circuit.parameter_count} detail="Trainable parameters" icon={<SlidersHorizontal size={15}/>}/></div><CircuitViz circuit={circuit}/><details className="mt-5 rounded-xl border p-4"><summary className="cursor-pointer text-xs font-semibold">Raw circuit text</summary><pre className="mono mt-3 max-h-[360px] overflow-auto whitespace-pre-wrap text-xs leading-relaxed">{circuit.text}</pre></details><JsonDisclosure label="Gate counts and limitations" value={{gate_counts:circuit.gate_counts,limitation:circuit.limitation}}/></Card>:<div className="mt-5"><EmptyState title="No circuit representation">Generate or retrieve a backend-described circuit.</EmptyState></div>}</div>
}

export function Explainability(){
 const {draft}=useDraft();
 const models=useQuery({queryKey:['models'],queryFn:qh.models});
 const experiments=useQuery({queryKey:['experiments'],queryFn:qh.experiments});
 const [scope,setScope]=useState<'active'|'all'>(draft.dataset_id?'active':'all');
 const visibleModels=contextModels(models.data,experiments.data,draft.dataset_id,scope);
 const [id,setId]=useState('');const [method,setMethod]=useState('permutation');const [samples,setSamples]=useState(8);const [repeats,setRepeats]=useState(3);const [maxFeatures,setMaxFeatures]=useState(30);
 useEffect(()=>{if(models.isSuccess&&experiments.isSuccess&&!visibleModels.some(model=>model.id===id))setId('')},[scope,draft.dataset_id,models.data,experiments.data,id,models.isSuccess,experiments.isSuccess]);
 const result=useQuery({queryKey:['explanations',id],queryFn:()=>qh.explanations(id),enabled:Boolean(id)});const selectedModel=visibleModels.find(model=>model.id===id);const effectiveMethod=isQiskitQuantumModel(selectedModel?.model_type)?'perturbation':isHybridModel(selectedModel?.model_type)?'shap':method;const run=useMutation({mutationFn:()=>qh.explain(id,{method:effectiveMethod,max_samples:samples,repeats,max_features:maxFeatures}),onSuccess:()=>result.refetch()});const current=result.data?.[0];
 return <div><PageHeader eyebrow="03 / Explain" title="Explainability" description="Drill into measured model behavior without turning feature influence into a medical causation claim." actions={<Link className="btn btn-outline" to="/prediction"><ArrowRight size={14}/>Prediction</Link>}/><StageNav current="/explainability"/><ErrorBanner error={(models.error as Error)?.message||(experiments.error as Error)?.message||(result.error as Error)?.message||(run.error as Error)?.message}/><Card className="mt-5" title="Explanation method"><div className="grid gap-4 md:grid-cols-2"><label className="field"><span>Model scope</span><Select aria-label="Explainability model scope" value={scope} onChange={e=>setScope(e.target.value as 'active'|'all')}><option value="active" disabled={!draft.dataset_id}>Active dataset + current experiment</option><option value="all">All registered models</option></Select></label><ModelSelect models={visibleModels} value={id} onChange={value=>{setId(value);const model=visibleModels.find(item=>item.id===value);if(isHybridModel(model?.model_type))setMethod('shap');else if(isQiskitQuantumModel(model?.model_type))setMethod('perturbation')}}/></div><div className="mt-4 grid gap-4 md:grid-cols-3"><label className="field"><span>Method</span><Select aria-label="Explanation method" value={effectiveMethod} disabled={isQiskitQuantumModel(selectedModel?.model_type)||isHybridModel(selectedModel?.model_type)} onChange={e=>setMethod(e.target.value)}><option value="permutation">Permutation</option><option value="shap">{isHybridModel(selectedModel?.model_type)?'SHAP — Final Hybrid Output':'SHAP'}</option><option value="perturbation">Perturbation</option></Select></label>{isHybridModel(selectedModel?.model_type)&&<div className="rounded-xl border border-indigo-200 bg-indigo-50 p-3 text-xs text-indigo-900"><strong>SHAP explains contribution to the final PennyLane + PyTorch positive-class probability.</strong><p className="mt-1">It does not establish biological causation or fully explain quantum-circuit internals.</p></div>}<label className="field"><span>Samples</span><Input type="number" min="2" max="32" value={samples} onChange={e=>setSamples(Number(e.target.value))}/></label><label className="field"><span>Repeats</span><Input type="number" min="1" max="10" value={repeats} onChange={e=>setRepeats(Number(e.target.value))}/></label></div><Button className="mt-4" disabled={!id||run.isPending} onClick={()=>run.mutate()}><Play size={14}/>{run.isPending?'Calculating…':'Calculate explanation'}</Button></Card><div className="mt-5">{current?<Card title={current.result.title} description={current.result.scope}>{current.result.method_display&&<div className="mb-4 flex flex-wrap gap-2"><Badge tone="purple">{current.result.method_display}</Badge><Badge tone="blue">GLOBAL / DATASET-LEVEL</Badge><span className="text-xs muted">{current.result.explained_case_count} explained cases · {current.result.background_sample_count} training-background rows</span></div>}<p className="mb-3 text-xs muted">{current.result.units}</p><InfluenceBars items={current.result.influence}/><Notice tone="amber">SHAP explains how original input features influenced the final model output; it does not establish medical causation.</Notice><JsonDisclosure label="Measured influence and limitations" value={current.result}/></Card>:<EmptyState title="No explanation yet">Select a completed model and request a bounded explanation.</EmptyState>}</div></div>
}

function ShapContributionList({title,items}:{title:string;items:Influence[]}){
 return <div><h4 className="text-xs font-semibold uppercase tracking-wide">{title}</h4><div className="mt-2 space-y-2">{items.length?items.slice(0,8).map(item=><div className="rounded-lg border p-3" key={item.feature}><div className="flex items-center justify-between gap-3"><div><strong className="text-sm">{item.feature}</strong><small className="block muted">Original value: {item.original_value===null?'Missing':String(item.original_value)}</small></div><strong className={item.direction==='toward_positive'?'text-red-600':'text-blue-600'}>{(item.contribution??item.signed_mean??0)>=0?'+':''}{(item.contribution??item.signed_mean??0).toFixed(4)}</strong></div><p className="mt-1 text-xs muted">{item.interpretation}</p></div>):<p className="text-xs muted">No contribution in this direction.</p>}</div></div>;
}

export function PredictionPage(){
 const {draft}=useDraft();
 const models=useQuery({queryKey:['models'],queryFn:qh.models});
 const experiments=useQuery({queryKey:['experiments'],queryFn:qh.experiments});
 const [scope,setScope]=useState<'active'|'all'>(draft.dataset_id?'active':'all');
 const visibleModels=contextModels(models.data,experiments.data,draft.dataset_id,scope);
 const [id,setId]=useState('');const selected=visibleModels.find(model=>model.id===id);const schema=useQuery({queryKey:['schema',id],queryFn:()=>qh.schema(id),enabled:Boolean(id)});const [values,setValues]=useState<Record<string,string>>({});const [low,setLow]=useState(.33);const [high,setHigh]=useState(.66);const [influence,setInfluence]=useState(true);const sample=useMutation({mutationFn:()=>qh.sample(id),onSuccess:data=>setValues(Object.fromEntries(Object.entries(data.features).map(([key,value])=>[key,value===null?'':String(value)])))});const pred=useMutation({mutationFn:()=>{const row=Object.fromEntries((schema.data?.features||[]).map(field=>[field.name,values[field.name]===undefined||values[field.name]===''?null:field.type==='number'?Number(values[field.name]):values[field.name]]));return qh.predict(id,{samples:[row],risk_thresholds:[low,high],include_influence:influence})}});
 useEffect(()=>{setValues({});pred.reset()},[id]);
 useEffect(()=>{pred.reset()},[values]);
 useEffect(()=>{if(!visibleModels.some(model=>model.id===id))setId('')},[scope,draft.dataset_id,models.data,experiments.data,id]);
 return <div><PageHeader eyebrow="04 / Predict" title="Research prediction" description="Apply an exact completed-model input schema to an anonymous research sample. The interface keeps the output explicitly non-clinical."/><StageNav current="/prediction"/><ErrorBanner error={(models.error as Error)?.message||(experiments.error as Error)?.message||(schema.error as Error)?.message||(sample.error as Error)?.message||(pred.error as Error)?.message}/><Card className="mt-5" title="Completed model">{selected?.details.experiment_kind==='precomputed_verified_demo'&&<Notice tone="blue">Verified precomputed research model. Integrity is revalidated by the backend before loading or prediction.</Notice>}<div className="grid gap-4 md:grid-cols-2"><label className="field"><span>Model scope</span><Select aria-label="Prediction model scope" value={scope} onChange={e=>setScope(e.target.value as 'active'|'all')}><option value="active" disabled={!draft.dataset_id}>Active dataset + current experiment</option><option value="all">All registered models</option></Select></label><ModelSelect models={visibleModels} value={id} onChange={setId}/></div>{schema.data&&<><div className="mt-4 flex flex-wrap gap-2"><Button variant="outline" disabled={!id||sample.isPending} onClick={()=>sample.mutate()}>{sample.isPending?'Loading sample…':'Load one public benchmark sample'}</Button><Badge tone="amber">No patient data</Badge></div><div className="mt-4 grid gap-3 md:grid-cols-3">{schema.data.features.map(field=><label className="field" key={field.name}><span>{field.name}</span><Input type={field.type==='number'?'number':'text'} value={values[field.name]||''} onChange={e=>setValues(state=>({...state,[field.name]:e.target.value}))} placeholder="Missing / impute"/></label>)}</div></>}{sample.data&&<Notice tone="blue">Loaded: {sample.data.sample} · Source: {sample.data.source}</Notice>}<div className="mt-4 grid gap-4 md:grid-cols-3"><label className="field"><span>Low threshold</span><Input type="number" min=".01" max=".98" step=".01" value={low} onChange={e=>setLow(Number(e.target.value))}/></label><label className="field"><span>High threshold</span><Input type="number" min=".02" max=".99" step=".01" value={high} onChange={e=>setHigh(Number(e.target.value))}/></label><label className="flex items-center gap-2 pt-6 text-xs"><input type="checkbox" checked={influence} onChange={e=>setInfluence(e.target.checked)}/>Local feature influence</label></div><Button className="mt-4" disabled={!schema.data||pred.isPending||!(0<low&&low<high&&high<1)} onClick={()=>pred.mutate()}><Play size={14}/>{pred.isPending?'Calculating…':'Generate research prediction'}</Button></Card><div className="mt-5">{pred.data?<Card title={isHybridModel(selected?.model_type)?"Why was this case flagged?":"Model-generated result"} description={pred.data.probability_status}><Notice tone="blue">Research operating point: {pred.data.decision_rule}. Source: {pred.data.threshold_source.replaceAll('_',' ')}. Not a clinically validated screening cutoff.</Notice>{pred.data.predictions.map(item=><div className="rounded-xl border p-4" key={item.sample}><div className="grid gap-4 md:grid-cols-3"><div><span className="metric-label">Predicted class</span><strong className="mt-1 block text-xl">{item.predicted_class}</strong></div><div><span className="metric-label">Probability</span><strong className="mt-1 block text-xl">{item.probability_positive===null?'Not available':metric(item.probability_positive)}</strong></div><div><span className="metric-label">Research category</span><strong className="mt-1 block text-xl">{item.research_risk_category||'Not assigned'}</strong></div></div></div>)}{pred.data.explanation?<div className="mt-5"><div className="flex flex-wrap items-center gap-2"><Badge tone="purple">PENNYLANE + PYTORCH HYBRID</Badge><Badge tone="blue">{pred.data.explanation.method_display}</Badge></div><h3 className="mt-3 text-lg font-semibold">Why was this case flagged?</h3><p className="text-xs muted">SHAP explains contributions to the final positive-class probability for this exact request.</p><div className="mt-4 grid gap-3 md:grid-cols-3"><MetricCard label="PROBABILITY" value={metric(pred.data.explanation.prediction_context.probability_positive)} detail="Final hybrid output"/><MetricCard label="OPERATING THRESHOLD" value={pred.data.explanation.prediction_context.operating_threshold.toFixed(4)} detail={pred.data.explanation.prediction_context.threshold_source.replaceAll('_',' ')}/><MetricCard label="PREDICTION" value={pred.data.explanation.prediction_context.predicted_class} detail={pred.data.explanation.prediction_context.research_risk_category||'No research category'}/></div><div className="mt-5 grid gap-5 lg:grid-cols-2"><ShapContributionList title="Pushed toward positive class" items={pred.data.explanation.contributions.filter(item=>item.direction==='toward_positive')}/><ShapContributionList title="Pushed toward negative class" items={pred.data.explanation.contributions.filter(item=>item.direction==='toward_negative')}/></div><Notice tone="amber">{pred.data.explanation.limitations[0]}</Notice></div>:pred.data.influence&&<><h3 className="mt-5 font-semibold">Local feature influence</h3><InfluenceBars items={pred.data.influence}/><Notice tone="amber">Feature influence reflects model behavior, not biological causation or clinical diagnosis.</Notice></>}<JsonDisclosure label="Decision rule and limitations" value={pred.data}/></Card>:<EmptyState title="No prediction calculated">Select a completed model and submit one anonymous sample.</EmptyState>}</div></div>
}

